-- Synthetic isolated tests, rollback only. Frozen public0.1.1 fixture derived
-- from buildLibrarySeed; digest assertions detect drift, not a mutable catalogue.
begin;
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('99134200-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.ok(v boolean,m text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'ASSERTION: %',m;end if;end$$;
insert into auth.users(id,email) select pg_temp.id(n),'asset-report-source-'||n||'@example.invalid' from generate_series(1,12)n;
insert into public.users(id,email,is_axiom_internal) select pg_temp.id(n),'asset-report-source-'||n||'@example.invalid',n in (1,2) from generate_series(1,12)n;
insert into public.tenants(id,slug,name) values(pg_temp.id(31),'asset-report-source-a','A'),(pg_temp.id(32),'asset-report-source-b','B');
insert into public.tenant_users(tenant_id,user_id,role) select pg_temp.id(31),pg_temp.id(n::integer),r::public.user_role from unnest(array['founder','axiom_analyst','owner','admin','reviewer','viewer','approver','partner','agent']) with ordinality t(r,n);
insert into public.control_libraries(version,published_at,published_by,change_log,control_count,status) values('0.1.1','2026-09-20','Axiom Minds · Founder','0.1.1 — CITATION CORRECTION (PATCH; assessments remain comparable).

The DPDPR-2025 citations were authored against the DRAFT Rules numbering and
were never re-mapped after notification, so 21 of 24 pointed at the wrong rule.
Reports generated against 0.1.0 cite the wrong law for notice, breach
notification, retention, cross-border transfer, data-principal rights and SDF
obligations. All 24 re-mapped against the Gazette text of G.S.R. 846(E) and
verified on 2026-09-20; each citation now records what it was verified against.

Header facts corrected: notification is 13 November 2025 (not 14 — the Gazette
issue is dated the 13th, and every commencement date is computed from it);
there are 23 rules (not "rules 5-24"); children''s-data controls follow Rule 10
(not "Rules 9-10"); SDF controls follow Rule 13 (not "Rules 11-12").

No control''s obligation, evidence requirement, question, scoring or remediation
pattern changed. Control count unchanged; the ~19 controls for the 10 uncited
rules and 7 schedules land in 0.2.0 as a MINOR.',46,'published');
insert into public.controls select (jsonb_populate_record(null::public.controls,value||jsonb_build_object('created_at',now()))).* from jsonb_array_elements($seed$[{"id":"DPDPA-GOV-001","library_version":"0.1.1","title":"Designate a data fiduciary accountable for DPDPA compliance","obligation":"Every entity that determines the purpose and means of processing digital personal data is a Data Fiduciary and bears primary statutory accountability under Section 8 of the DPDP Act, regardless of contract structure.","domain":"GOV","severity":"critical","citations":[{"instrument":"DPDPA-2023","reference":"Section 2(i), 2(k), 8(1)"}],"evidence_required":[{"type":"document","description":"Board resolution or partnership deed naming the Data Fiduciary entity"},{"type":"config","description":"Authoritative organisational record (MCA / GST filing) showing the entity"}],"assessment_questions":[{"id":"Q1","prompt":"Is there a single legal entity formally identified as the Data Fiduciary for the personal data you process?","type":"boolean","evidenceTypes":["document","config"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":30,"maxPenaltyINR":250000000},"remediation_patterns":["dpo-appointment","review"],"tags":["foundation","always-applies"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-GOV-002","library_version":"0.1.1","title":"Publish a privacy policy covering all processing activities","obligation":"A publicly accessible privacy policy must describe the personal data processed, the purposes, the rights of data principals, and contact information for grievance redressal (Section 5(3) read with Rule 3).","domain":"GOV","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 5(3)"},{"instrument":"DPDPR-2025","reference":"Rule 3"}],"evidence_required":[{"type":"document","description":"Public privacy policy URL with version + effective date"},{"type":"screenshot","description":"Live screenshot of the published policy"}],"assessment_questions":[{"id":"Q1","prompt":"Do you have a publicly accessible privacy policy that meets Section 5(3) requirements?","type":"boolean","evidenceTypes":["document","screenshot"],"dependsOn":[]},{"id":"Q2","prompt":"When was the policy last reviewed and is the version date visible on the page?","type":"evidence","evidenceTypes":["screenshot"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":18,"maxPenaltyINR":50000000},"remediation_patterns":["policy"],"tags":["always-applies","public-facing"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-GOV-003","library_version":"0.1.1","title":"Maintain a written data-processing agreement with every Data Processor","obligation":"Personal data may be processed by a Data Processor only under a valid contract that limits processing to the Data Fiduciary's instructions, enforces security safeguards, and binds the processor to the Act (Section 8(1), Rule 6).","domain":"GOV","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 8(1), 2(l)"},{"instrument":"DPDPR-2025","reference":"Rule 6"}],"evidence_required":[{"type":"document","description":"Signed DPA with each processor covering scope, security, sub-processors, return/deletion"}],"assessment_questions":[{"id":"Q1","prompt":"List all third parties that process personal data on your behalf (Data Processors).","type":"text","evidenceTypes":["document"],"dependsOn":[]},{"id":"Q2","prompt":"For each processor, is there a signed DPA that meets Rule 6 requirements?","type":"evidence","evidenceTypes":["document"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":20,"maxPenaltyINR":50000000},"remediation_patterns":["dpa-execution","vendor-risk"],"tags":["always-applies","vendor"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-CNS-001","library_version":"0.1.1","title":"Obtain free, specific, informed, unconditional, unambiguous consent","obligation":"Consent must be free, specific, informed, unconditional and unambiguous, with a clear affirmative action, and must be capable of being withdrawn as easily as it was given (Section 6(1)–(4)).","domain":"CNS","severity":"critical","citations":[{"instrument":"DPDPA-2023","reference":"Section 6(1), 6(2), 6(3), 6(4)"},{"instrument":"DPDPR-2025","reference":"Rule 3"}],"evidence_required":[{"type":"screenshot","description":"Screenshot of the consent capture UX showing it is un-bundled and affirmative"},{"type":"log","description":"Sample of consent records with timestamp and version of notice shown"}],"assessment_questions":[{"id":"Q1","prompt":"Is consent obtained via a clear affirmative action (not pre-ticked boxes or implied consent)?","type":"boolean","evidenceTypes":["screenshot","config"],"dependsOn":[]},{"id":"Q2","prompt":"Is the consent notice shown at the time of consent and version-pinned?","type":"boolean","evidenceTypes":["screenshot","log"],"dependsOn":[]},{"id":"Q3","prompt":"Can the data principal withdraw consent as easily as they gave it?","type":"boolean","evidenceTypes":["screenshot","config"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":35,"maxPenaltyINR":250000000},"remediation_patterns":["consent","policy"],"tags":["always-applies","first-principle"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-CNS-002","library_version":"0.1.1","title":"Issue notice before or alongside consent specifying purpose, items, and rights","obligation":"Before seeking consent the Data Fiduciary must issue a notice describing the personal data and the purpose of processing, the manner of exercising rights, and the means of making a complaint (Section 5(1)–(2), Rule 3).","domain":"CNS","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 5(1), 5(2)"},{"instrument":"DPDPR-2025","reference":"Rule 3"}],"evidence_required":[{"type":"document","description":"Consent notice text showing all required items"},{"type":"screenshot","description":"Live UI showing notice at point of consent"}],"assessment_questions":[{"id":"Q1","prompt":"Does the notice describe the personal data items being collected and the specific purpose?","type":"boolean","evidenceTypes":["document"],"dependsOn":[]},{"id":"Q2","prompt":"Does the notice explain how to exercise rights and how to make a complaint?","type":"boolean","evidenceTypes":["document"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":20,"maxPenaltyINR":50000000},"remediation_patterns":["policy","consent"],"tags":["always-applies"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-CNS-003","library_version":"0.1.1","title":"Maintain a consent ledger with at least 7-year retention","obligation":"Records of consent — including the notice version, the data principal identifier, the timestamp, and the items consented to — must be retained for at least 7 years from the date of consent or last action, whichever is later (Rule 4 read with the First Schedule).","domain":"CNS","severity":"high","citations":[{"instrument":"DPDPR-2025","reference":"Rule 4 and First Schedule"}],"evidence_required":[{"type":"config","description":"Schema + retention policy showing 7-year retention on consent records"},{"type":"log","description":"Sample consent record with all required fields"}],"assessment_questions":[{"id":"Q1","prompt":"Do you store a record of every consent with timestamp + notice version + items + data principal ID?","type":"boolean","evidenceTypes":["config","log"],"dependsOn":[]},{"id":"Q2","prompt":"Is the retention period at least 7 years?","type":"boolean","evidenceTypes":["config"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":18,"maxPenaltyINR":50000000},"remediation_patterns":["config","policy"],"tags":["always-applies","retention"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-CNS-004","library_version":"0.1.1","title":"Honor consent withdrawal and erase related data","obligation":"On withdrawal of consent, processing must stop and personal data must be erased within a reasonable time, except where retention is necessary for legal obligation (Section 6(4), 8(7)).","domain":"CNS","severity":"critical","citations":[{"instrument":"DPDPA-2023","reference":"Section 6(4), 8(7)"}],"evidence_required":[{"type":"log","description":"Withdrawal workflow showing receipt → action → completion"},{"type":"attestation","description":"Policy on what is erased vs retained and why"}],"assessment_questions":[{"id":"Q1","prompt":"Is there a working mechanism for users to withdraw consent?","type":"boolean","evidenceTypes":["screenshot","config"],"dependsOn":[]},{"id":"Q2","prompt":"After withdrawal, is the user's personal data erased from active systems within a reasonable time?","type":"boolean","evidenceTypes":["log","attestation"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":30,"maxPenaltyINR":250000000},"remediation_patterns":["data-deletion","consent","config"],"tags":["always-applies","rights"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-CNS-005","library_version":"0.1.1","title":"Publish an itemised list of personal data collected for each purpose","obligation":"The notice must itemise the personal data being collected and the specific purpose, not generic categories. \"Personal data\" must be itemised at a level a data principal can understand and consent to specifically.","domain":"CNS","severity":"medium","citations":[{"instrument":"DPDPA-2023","reference":"Section 5(1)(b)"},{"instrument":"DPDPR-2025","reference":"Rule 3"}],"evidence_required":[{"type":"document","description":"Notice text showing itemised fields"}],"assessment_questions":[{"id":"Q1","prompt":"For each processing purpose, does the notice itemise the specific data fields collected?","type":"boolean","evidenceTypes":["document"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":12,"maxPenaltyINR":50000000},"remediation_patterns":["policy"],"tags":["always-applies"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-DAT-001","library_version":"0.1.1","title":"Provide a right-of-access mechanism (summary of personal data held)","obligation":"A data principal has the right to obtain a summary of their personal data being processed and the related processing activities (Section 11(1), Rule 14).","domain":"DAT","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 11(1)"},{"instrument":"DPDPR-2025","reference":"Rule 14"}],"evidence_required":[{"type":"config","description":"DSAR intake + identity verification flow"},{"type":"log","description":"Sample of past fulfilled access requests"}],"assessment_questions":[{"id":"Q1","prompt":"Can a data principal request a copy of their personal data you hold?","type":"boolean","evidenceTypes":["screenshot","config"],"dependsOn":[]},{"id":"Q2","prompt":"Within what timeframe do you respond?","type":"text","evidenceTypes":["attestation"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":20,"maxPenaltyINR":50000000},"remediation_patterns":["review","policy","data-portability"],"tags":["always-applies","rights"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-DAT-002","library_version":"0.1.1","title":"Provide right to correction and erasure of personal data","obligation":"A data principal may request correction or erasure of their personal data where it is incomplete, inaccurate, or no longer necessary (Section 12, Rule 14).","domain":"DAT","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 12"},{"instrument":"DPDPR-2025","reference":"Rule 14"}],"evidence_required":[{"type":"config","description":"Correction/erasure request workflow"},{"type":"log","description":"Sample of completed correction/erasure requests"}],"assessment_questions":[{"id":"Q1","prompt":"Can a data principal request correction of inaccurate personal data?","type":"boolean","evidenceTypes":["screenshot","config"],"dependsOn":[]},{"id":"Q2","prompt":"Can a data principal request erasure of personal data, and do you action it across all systems (including processors)?","type":"boolean","evidenceTypes":["screenshot","config","log"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":22,"maxPenaltyINR":50000000},"remediation_patterns":["data-deletion","config","policy"],"tags":["always-applies","rights"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-DAT-003","library_version":"0.1.1","title":"Operate a grievance redressal mechanism with named contact","obligation":"The Data Fiduciary must establish a grievance redressal mechanism and respond to data principal complaints within 30 days, with the name and contact details of the grievance officer published (Section 13(1), Rule 14).","domain":"DAT","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 13(1)"},{"instrument":"DPDPR-2025","reference":"Rule 14"}],"evidence_required":[{"type":"document","description":"Published grievance officer name and contact"},{"type":"log","description":"Grievance ticketing with response time tracking"}],"assessment_questions":[{"id":"Q1","prompt":"Is the grievance officer name and contact publicly available?","type":"boolean","evidenceTypes":["document","screenshot"],"dependsOn":[]},{"id":"Q2","prompt":"Do you respond to complaints within 30 days?","type":"boolean","evidenceTypes":["log","attestation"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":18,"maxPenaltyINR":50000000},"remediation_patterns":["policy","dpo-appointment"],"tags":["always-applies"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-DAT-004","library_version":"0.1.1","title":"Provide right to nominate another individual","obligation":"A data principal may nominate another individual to exercise their rights in the event of death or incapacity (Section 14).","domain":"DAT","severity":"medium","citations":[{"instrument":"DPDPA-2023","reference":"Section 14"}],"evidence_required":[{"type":"config","description":"Nomination feature in user account"},{"type":"document","description":"Notice describing the right"}],"assessment_questions":[{"id":"Q1","prompt":"Can a user nominate another individual to exercise their rights?","type":"boolean","evidenceTypes":["screenshot","config"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":8,"maxPenaltyINR":20000000},"remediation_patterns":["config","policy"],"tags":["always-applies","rights"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-RCD-001","library_version":"0.1.1","title":"Maintain a Record of Processing Activities (RoPA)","obligation":"The Data Fiduciary must maintain accurate and up-to-date records of its processing activities, sufficient to demonstrate compliance (Rule 8 read with the Third Schedule).","domain":"RCD","severity":"high","citations":[{"instrument":"DPDPR-2025","reference":"Rule 8 and Third Schedule"},{"instrument":"DPDPA-2023","reference":"Section 8"}],"evidence_required":[{"type":"inventory","description":"Living RoPA — purpose, data items, lawful basis, processors, retention, cross-border"}],"assessment_questions":[{"id":"Q1","prompt":"Do you maintain a written Record of Processing Activities?","type":"boolean","evidenceTypes":["inventory","document"],"dependsOn":[]},{"id":"Q2","prompt":"Is it updated within 30 days of any change in processing?","type":"boolean","evidenceTypes":["attestation"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":18,"maxPenaltyINR":50000000},"remediation_patterns":["discovery","reporting"],"tags":["always-applies","core"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-RCD-002","library_version":"0.1.1","title":"Capture a complete data inventory (systems, fields, flows)","obligation":"The RoPA must be backed by an actual inventory of systems, databases, fields and data flows — not a generic narrative. Records must be available on demand to the Data Protection Board.","domain":"RCD","severity":"high","citations":[{"instrument":"DPDPR-2025","reference":"Rule 6"}],"evidence_required":[{"type":"inventory","description":"System-level inventory with field-level personal-data classification"}],"assessment_questions":[{"id":"Q1","prompt":"Have you inventoried all systems that hold personal data?","type":"boolean","evidenceTypes":["inventory"],"dependsOn":[]},{"id":"Q2","prompt":"Is the inventory field-level (not just system-level)?","type":"boolean","evidenceTypes":["inventory"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":18,"maxPenaltyINR":50000000},"remediation_patterns":["discovery"],"tags":["always-applies","core"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-BRCH-001","library_version":"0.1.1","title":"Notify the Data Protection Board of a personal data breach","obligation":"On becoming aware of a personal data breach, the Data Fiduciary must inform the Data Protection Board and the affected data principals in the manner and within the time prescribed (Section 8(6), Rules 19–20).","domain":"BRCH","severity":"critical","citations":[{"instrument":"DPDPA-2023","reference":"Section 8(6)"},{"instrument":"DPDPR-2025","reference":"Rule 7"}],"evidence_required":[{"type":"document","description":"Breach response runbook with 72-hour DPB clock"},{"type":"log","description":"Forensic log capture capability"}],"assessment_questions":[{"id":"Q1","prompt":"Do you have a documented breach response procedure?","type":"boolean","evidenceTypes":["document"],"dependsOn":[]},{"id":"Q2","prompt":"Can you meet the statutory notification clock (typically 72 hours from awareness)?","type":"boolean","evidenceTypes":["attestation","log"],"dependsOn":[]},{"id":"Q3","prompt":"Do you have forensic log capture sufficient to reconstruct a breach?","type":"boolean","evidenceTypes":["log","config"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":40,"maxPenaltyINR":250000000},"remediation_patterns":["breach-process","policy"],"tags":["always-applies","high-stakes"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-BRCH-002","library_version":"0.1.1","title":"Notify affected data principals of a breach where harm is likely","obligation":"Where a breach is likely to cause harm to a data principal, the Data Fiduciary must inform affected principals without delay, in plain language, of the nature of the breach and the protective measures (Rule 7).","domain":"BRCH","severity":"high","citations":[{"instrument":"DPDPR-2025","reference":"Rule 7"}],"evidence_required":[{"type":"document","description":"Principal notification template and trigger criteria"}],"assessment_questions":[{"id":"Q1","prompt":"Do you have a template for notifying affected principals?","type":"boolean","evidenceTypes":["document"],"dependsOn":[]},{"id":"Q2","prompt":"Is the trigger criteria for principal notification defined?","type":"boolean","evidenceTypes":["document"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":22,"maxPenaltyINR":50000000},"remediation_patterns":["breach-process","policy"],"tags":["always-applies"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-XBR-001","library_version":"0.1.1","title":"Restrict cross-border transfer to countries not on the restricted list","obligation":"Personal data may be transferred outside India only to countries or territories not specifically restricted by the Central Government via notification (Section 16, Rule 15).","domain":"XBR","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 16"},{"instrument":"DPDPR-2025","reference":"Rule 15"}],"evidence_required":[{"type":"inventory","description":"Data flow map showing all cross-border destinations"},{"type":"document","description":"Policy and DPA clauses restricting transfer to allowed jurisdictions"}],"assessment_questions":[{"id":"Q1","prompt":"Do you transfer any personal data outside India?","type":"boolean","evidenceTypes":["inventory"],"dependsOn":[]},{"id":"Q2","prompt":"If yes, are all destinations confirmed not on the restricted list (as notified by the Central Government)?","type":"boolean","evidenceTypes":["document","attestation"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":25,"maxPenaltyINR":50000000},"remediation_patterns":["vendor-risk","dpa-execution","policy"],"tags":["always-applies","cross-border"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-XBR-002","library_version":"0.1.1","title":"Document the legal basis for any cross-border transfer","obligation":"Every cross-border transfer must be supported by a specific contract clause, consent, or other lawful basis that meets Section 16 requirements.","domain":"XBR","severity":"medium","citations":[{"instrument":"DPDPA-2023","reference":"Section 16"}],"evidence_required":[{"type":"document","description":"Transfer impact assessment or contract clauses"}],"assessment_questions":[{"id":"Q1","prompt":"For each cross-border transfer, is the legal basis documented?","type":"boolean","evidenceTypes":["document"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":15,"maxPenaltyINR":50000000},"remediation_patterns":["dpa-execution","policy"],"tags":["cross-border"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-CHD-001","library_version":"0.1.1","title":"Obtain verifiable parental consent before processing children's data","obligation":"Personal data of children (under 18) may be processed only with verifiable parental consent, and processing must not be detrimental to the well-being of the child (Section 9, Rule 10).","domain":"CHD","severity":"critical","citations":[{"instrument":"DPDPA-2023","reference":"Section 9"},{"instrument":"DPDPR-2025","reference":"Rule 10"}],"evidence_required":[{"type":"config","description":"Age-gate + parental consent flow"},{"type":"document","description":"Age-appropriate notice language"}],"assessment_questions":[{"id":"Q1","prompt":"Do you process data of children (users under 18)?","type":"boolean","evidenceTypes":["inventory"],"dependsOn":[]},{"id":"Q2","prompt":"If yes, do you obtain verifiable parental consent before processing?","type":"boolean","evidenceTypes":["config","log"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":35,"maxPenaltyINR":250000000},"remediation_patterns":["consent","config","policy"],"tags":["children"],"sdf_only":false,"children_only":true,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-CHD-002","library_version":"0.1.1","title":"Refuse to undertake tracking or behavioural monitoring of children","obligation":"Data Fiduciaries must not undertake tracking, behavioural monitoring, or targeted advertising directed at children (Section 9(2), Rule 10).","domain":"CHD","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 9(2)"},{"instrument":"DPDPR-2025","reference":"Rule 10"}],"evidence_required":[{"type":"config","description":"Ad-tech and analytics exclusion for child users"},{"type":"attestation","description":"Internal policy on no-targeted-ads-to-children"}],"assessment_questions":[{"id":"Q1","prompt":"Do you run any tracking, behavioural monitoring, or targeted advertising that could reach children?","type":"boolean","evidenceTypes":["config","attestation"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":25,"maxPenaltyINR":50000000},"remediation_patterns":["config","policy"],"tags":["children"],"sdf_only":false,"children_only":true,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-SDF-001","library_version":"0.1.1","title":"Appoint a Data Protection Officer (India-based, named)","obligation":"A Significant Data Fiduciary must appoint a Data Protection Officer based in India who reports to the board, and publish their name and contact (Section 10, Rule 13).","domain":"SDF","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 10"},{"instrument":"DPDPR-2025","reference":"Rule 13"}],"evidence_required":[{"type":"document","description":"DPO appointment letter, India-based address, board reporting line"},{"type":"config","description":"Public DPO contact on website"}],"assessment_questions":[{"id":"Q1","prompt":"Have you been designated as a Significant Data Fiduciary by the Central Government?","type":"boolean","evidenceTypes":["document","attestation"],"dependsOn":[]},{"id":"Q2","prompt":"If yes, have you appointed a Data Protection Officer based in India and published their contact?","type":"boolean","evidenceTypes":["document","screenshot"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":22,"maxPenaltyINR":50000000},"remediation_patterns":["dpo-appointment","policy"],"tags":["SDF"],"sdf_only":true,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-SDF-002","library_version":"0.1.1","title":"Conduct periodic Data Protection Impact Assessments (DPIA)","obligation":"A Significant Data Fiduciary must conduct periodic Data Protection Impact Assessments, including for any processing that is likely to cause harm to a data principal (Section 10, Rule 13).","domain":"SDF","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 10"},{"instrument":"DPDPR-2025","reference":"Rule 13"}],"evidence_required":[{"type":"document","description":"DPIA template + completed DPIA artifacts"}],"assessment_questions":[{"id":"Q1","prompt":"Are DPIAs conducted at least annually, and prior to any new high-risk processing?","type":"boolean","evidenceTypes":["document"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":20,"maxPenaltyINR":50000000},"remediation_patterns":["review","reporting","policy"],"tags":["SDF"],"sdf_only":true,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-SDF-003","library_version":"0.1.1","title":"Submit to periodic audit by an independent Data Auditor","obligation":"A Significant Data Fiduciary must be audited periodically by an independent Data Auditor, and the audit report must be submitted to the Board (Section 10, Rule 13).","domain":"SDF","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 10"},{"instrument":"DPDPR-2025","reference":"Rule 13"}],"evidence_required":[{"type":"document","description":"Independent audit engagement + latest audit report"}],"assessment_questions":[{"id":"Q1","prompt":"Are you audited annually by an independent Data Auditor?","type":"boolean","evidenceTypes":["document"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":20,"maxPenaltyINR":50000000},"remediation_patterns":["reporting","vendor-risk"],"tags":["SDF"],"sdf_only":true,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-SEC-001","library_version":"0.1.1","title":"Implement reasonable security safeguards (technical + organisational)","obligation":"The Data Fiduciary must protect personal data in its possession by taking reasonable security safeguards to prevent personal data breach (Section 8(5)). Failure constitutes grounds for the highest penalty tier under Section 33(7).","domain":"SEC","severity":"critical","citations":[{"instrument":"DPDPA-2023","reference":"Section 8(5)"},{"instrument":"DPDPR-2025","reference":"Rule 6"}],"evidence_required":[{"type":"config","description":"Encryption at rest + in transit, access controls, MFA, logging"},{"type":"document","description":"Security policy + incident response plan"}],"assessment_questions":[{"id":"Q1","prompt":"Is personal data encrypted at rest (AES-256 or equivalent) and in transit (TLS 1.2+)?","type":"boolean","evidenceTypes":["config"],"dependsOn":[]},{"id":"Q2","prompt":"Is multi-factor authentication enforced for administrative access to personal data stores?","type":"boolean","evidenceTypes":["config"],"dependsOn":[]},{"id":"Q3","prompt":"Is access to personal data logged and reviewed?","type":"boolean","evidenceTypes":["log","config"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":50,"maxPenaltyINR":250000000},"remediation_patterns":["config","policy","training"],"tags":["always-applies","foundation"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-SEC-002","library_version":"0.1.1","title":"Enforce least-privilege access to personal data","obligation":"Access to personal data must be limited to personnel who require it for the documented purpose, with role-based access controls and periodic access review.","domain":"SEC","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 8(5)"}],"evidence_required":[{"type":"config","description":"RBAC configuration + access review logs"}],"assessment_questions":[{"id":"Q1","prompt":"Is access to personal data gated by role-based access control?","type":"boolean","evidenceTypes":["config"],"dependsOn":[]},{"id":"Q2","prompt":"Are access rights reviewed at least annually?","type":"boolean","evidenceTypes":["log","attestation"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":20,"maxPenaltyINR":50000000},"remediation_patterns":["config","review","policy"],"tags":["always-applies"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-SEC-003","library_version":"0.1.1","title":"Maintain audit logs of access and processing of personal data","obligation":"Comprehensive, tamper-evident logs of who accessed or processed personal data, when, and for what purpose must be maintained for forensic and regulatory use.","domain":"SEC","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 8(5)"}],"evidence_required":[{"type":"log","description":"Append-only, hash-chained audit ledger"}],"assessment_questions":[{"id":"Q1","prompt":"Are all access and processing events recorded to an append-only audit log?","type":"boolean","evidenceTypes":["log","config"],"dependsOn":[]},{"id":"Q2","prompt":"Is the log tamper-evident (e.g. hash-chained, write-once)?","type":"boolean","evidenceTypes":["config"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":20,"maxPenaltyINR":50000000},"remediation_patterns":["config","review"],"tags":["always-applies","audit"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-SEC-004","library_version":"0.1.1","title":"Conduct periodic vulnerability assessment and penetration testing","obligation":"Personal-data-bearing systems should be subject to periodic vulnerability assessment and penetration testing, with findings remediated within a defined SLA.","domain":"SEC","severity":"medium","citations":[{"instrument":"DPDPA-2023","reference":"Section 8(5)"}],"evidence_required":[{"type":"document","description":"Latest VAPT report + remediation evidence"}],"assessment_questions":[{"id":"Q1","prompt":"When was your last VAPT?","type":"text","evidenceTypes":["document"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":12,"maxPenaltyINR":50000000},"remediation_patterns":["review","policy"],"tags":["always-applies"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-SEC-005","library_version":"0.1.1","title":"Encrypt backups of personal data","obligation":"Backups containing personal data must be encrypted and access-controlled at the same standard as the primary system.","domain":"SEC","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 8(5)"}],"evidence_required":[{"type":"config","description":"Backup encryption configuration"}],"assessment_questions":[{"id":"Q1","prompt":"Are backups encrypted at rest?","type":"boolean","evidenceTypes":["config"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":15,"maxPenaltyINR":50000000},"remediation_patterns":["config"],"tags":["always-applies","ops"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-RTN-001","library_version":"0.1.1","title":"Define and enforce a retention schedule for personal data","obligation":"Personal data must be retained only for as long as necessary to satisfy the purpose for which it was collected, and erased thereafter (Section 8(7)).","domain":"RTN","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 8(7)"}],"evidence_required":[{"type":"document","description":"Written retention schedule with purpose-linked durations"},{"type":"config","description":"System-level enforcement of retention + deletion"}],"assessment_questions":[{"id":"Q1","prompt":"Do you have a written retention schedule for each category of personal data?","type":"boolean","evidenceTypes":["document"],"dependsOn":[]},{"id":"Q2","prompt":"Is retention enforced automatically in your systems?","type":"boolean","evidenceTypes":["config"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":18,"maxPenaltyINR":50000000},"remediation_patterns":["config","policy","data-deletion"],"tags":["always-applies"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-RTN-002","library_version":"0.1.1","title":"Erase personal data upon purpose-end or withdrawal","obligation":"On the conclusion of the processing purpose, or on consent withdrawal, the Data Fiduciary must erase the personal data unless retention is required for legal obligation (Section 8(7)).","domain":"RTN","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 8(7)"}],"evidence_required":[{"type":"log","description":"Erasure workflow + sample completed erasures"}],"assessment_questions":[{"id":"Q1","prompt":"Is erasure performed on the documented trigger (purpose end / withdrawal / retention expiry)?","type":"boolean","evidenceTypes":["log","config"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":18,"maxPenaltyINR":50000000},"remediation_patterns":["data-deletion","config"],"tags":["always-applies"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-RTN-003","library_version":"0.1.1","title":"Maintain an exception register for legally-required retention","obligation":"Where erasure is deferred for a legal obligation (e.g. tax, AML, litigation hold), the basis, scope, and the responsible officer must be recorded in a register that an auditor or the Board can review.","domain":"RTN","severity":"medium","citations":[{"instrument":"DPDPA-2023","reference":"Section 8(7)"}],"evidence_required":[{"type":"document","description":"Exception register with reason, scope, owner, expiry"}],"assessment_questions":[{"id":"Q1","prompt":"Do you maintain a register of records retained for legal obligation rather than erased?","type":"boolean","evidenceTypes":["document"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":8,"maxPenaltyINR":20000000},"remediation_patterns":["policy","reporting"],"tags":["always-applies"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-DPF-001","library_version":"0.1.1","title":"Publish contact details for privacy inquiries","obligation":"An email and a contact mechanism for privacy inquiries must be publicly available; this can be a grievance officer or a DPO depending on the entity's SDF status.","domain":"DPF","severity":"medium","citations":[{"instrument":"DPDPA-2023","reference":"Section 5(3)(d), 13(1)"}],"evidence_required":[{"type":"screenshot","description":"Public contact details"}],"assessment_questions":[{"id":"Q1","prompt":"Is a privacy contact email publicly listed?","type":"boolean","evidenceTypes":["screenshot","document"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":8,"maxPenaltyINR":20000000},"remediation_patterns":["policy","dpo-appointment"],"tags":["always-applies"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-DPF-002","library_version":"0.1.1","title":"Designate a single point of accountability for privacy","obligation":"Even non-SDF Data Fiduciaries benefit from designating a single internal owner — typically a Privacy Lead — who is responsible for the privacy programme, escalation, and Board reporting.","domain":"DPF","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 8"}],"evidence_required":[{"type":"document","description":"Internal appointment / role description"}],"assessment_questions":[{"id":"Q1","prompt":"Is there a named individual accountable for the privacy programme?","type":"boolean","evidenceTypes":["document"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":15,"maxPenaltyINR":50000000},"remediation_patterns":["dpo-appointment","policy"],"tags":["always-applies"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-AUD-001","library_version":"0.1.1","title":"Maintain a continuous, timestamped evidence history of compliance","obligation":"A defensible compliance posture requires a continuous, timestamped, tamper-evident history of compliance evidence — not point-in-time documentation. This is the operational manifestation of the Act's \"demonstrate compliance\" burden.","domain":"AUD","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 8, 33"}],"evidence_required":[{"type":"log","description":"Append-only, hash-chained evidence ledger spanning the assessment period"}],"assessment_questions":[{"id":"Q1","prompt":"Can you produce, on demand, a verifiable, timestamped history of every compliance control for the past 12 months?","type":"boolean","evidenceTypes":["log","document"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":22,"maxPenaltyINR":50000000},"remediation_patterns":["review","reporting"],"tags":["always-applies","defensibility"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-AUD-002","library_version":"0.1.1","title":"Report posture to the Board or Audit Committee at least annually","obligation":"A periodic (at least annual) posture report to the Board or Audit Committee establishes governance accountability and provides defensible evidence of oversight.","domain":"AUD","severity":"medium","citations":[{"instrument":"DPDPA-2023","reference":"Section 8"}],"evidence_required":[{"type":"document","description":"Most recent Board / Audit Committee privacy report"}],"assessment_questions":[{"id":"Q1","prompt":"Has the Board / Audit Committee received a privacy posture update in the past 12 months?","type":"boolean","evidenceTypes":["document"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":10,"maxPenaltyINR":20000000},"remediation_patterns":["reporting","policy"],"tags":["always-applies","governance"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-DPIA-001","library_version":"0.1.1","title":"Conduct a DPIA before launching any new high-risk processing","obligation":"Where processing is likely to cause harm to data principals — large-scale profiling, biometric processing, children, cross-border — a Data Protection Impact Assessment must be completed before processing begins.","domain":"DPIA","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 10"},{"instrument":"DPDPR-2025","reference":"Rule 13"}],"evidence_required":[{"type":"document","description":"DPIA template + completed DPIAs for high-risk processing"}],"assessment_questions":[{"id":"Q1","prompt":"Do you conduct a DPIA before any new high-risk processing?","type":"boolean","evidenceTypes":["document"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":20,"maxPenaltyINR":50000000},"remediation_patterns":["review","policy"],"tags":["always-applies","high-risk"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-DPIA-002","library_version":"0.1.1","title":"Capture and remediate risks identified in the DPIA","obligation":"Risks identified in a DPIA must be tracked to closure with an owner, a remediation plan, and a re-assessment after remediation.","domain":"DPIA","severity":"high","citations":[{"instrument":"DPDPR-2025","reference":"Rule 13"}],"evidence_required":[{"type":"log","description":"DPIA risk register + closure evidence"}],"assessment_questions":[{"id":"Q1","prompt":"Are DPIA findings tracked in a risk register with owners and closure dates?","type":"boolean","evidenceTypes":["log","document"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":18,"maxPenaltyINR":50000000},"remediation_patterns":["review","reporting"],"tags":["high-risk"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-GOV-004","library_version":"0.1.1","title":"Maintain a current org chart of data processing responsibilities","obligation":"Roles and responsibilities for privacy must be visible and current — who decides purposes, who signs off on processors, who handles DSARs, who is on the breach call.","domain":"GOV","severity":"low","citations":[{"instrument":"DPDPA-2023","reference":"Section 8"}],"evidence_required":[{"type":"document","description":"RACI / org chart for privacy"}],"assessment_questions":[{"id":"Q1","prompt":"Is there a current RACI or org chart for privacy responsibilities?","type":"boolean","evidenceTypes":["document"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":5,"maxPenaltyINR":20000000},"remediation_patterns":["policy"],"tags":["governance"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-GOV-005","library_version":"0.1.1","title":"Conduct annual privacy training for staff handling personal data","obligation":"Personnel handling personal data must receive privacy training on induction and at least annually thereafter, with completion recorded.","domain":"GOV","severity":"medium","citations":[{"instrument":"DPDPA-2023","reference":"Section 8(5)"}],"evidence_required":[{"type":"log","description":"Training records with completion status"}],"assessment_questions":[{"id":"Q1","prompt":"Do all staff handling personal data receive annual privacy training?","type":"boolean","evidenceTypes":["log"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":10,"maxPenaltyINR":20000000},"remediation_patterns":["training","policy"],"tags":["always-applies","training"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-BRCH-003","library_version":"0.1.1","title":"Designate a breach response owner with a documented playbook","obligation":"A named individual must own breach response end-to-end, with a documented playbook covering detection → triage → notification → post-mortem, exercised at least annually.","domain":"BRCH","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 8(6)"}],"evidence_required":[{"type":"document","description":"Breach response playbook"},{"type":"attestation","description":"Tabletop exercise record"}],"assessment_questions":[{"id":"Q1","prompt":"Is there a named breach response owner and a current playbook?","type":"boolean","evidenceTypes":["document"],"dependsOn":[]},{"id":"Q2","prompt":"Has a tabletop exercise been run in the past 12 months?","type":"boolean","evidenceTypes":["attestation"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":18,"maxPenaltyINR":50000000},"remediation_patterns":["breach-process","policy"],"tags":["always-applies"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-RCD-003","library_version":"0.1.1","title":"Map and document data flows to processors and sub-processors","obligation":"Beyond the RoPA, a working data-flow map (system-of-systems diagram) showing personal data movement — including to sub-processors — must be available for the Board and any DPB inquiry.","domain":"RCD","severity":"high","citations":[{"instrument":"DPDPR-2025","reference":"Rule 8 and Third Schedule"}],"evidence_required":[{"type":"inventory","description":"Data flow diagram with processors and sub-processors"}],"assessment_questions":[{"id":"Q1","prompt":"Is there a current data-flow map showing processors and sub-processors?","type":"boolean","evidenceTypes":["inventory","document"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":18,"maxPenaltyINR":50000000},"remediation_patterns":["discovery","vendor-risk"],"tags":["always-applies"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-XBR-003","library_version":"0.1.1","title":"Conduct a transfer impact assessment for high-risk destinations","obligation":"For transfers to jurisdictions with materially different data protection regimes, a transfer impact assessment should be completed to demonstrate that the receiving environment provides comparable protection.","domain":"XBR","severity":"medium","citations":[{"instrument":"DPDPA-2023","reference":"Section 16"}],"evidence_required":[{"type":"document","description":"TIA per high-risk destination"}],"assessment_questions":[{"id":"Q1","prompt":"Have you completed a transfer impact assessment for each cross-border destination with weaker protection?","type":"boolean","evidenceTypes":["document"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":12,"maxPenaltyINR":50000000},"remediation_patterns":["vendor-risk","policy"],"tags":["cross-border"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-SEC-006","library_version":"0.1.1","title":"Securely dispose of media and devices containing personal data","obligation":"Media and devices containing personal data, including at end-of-life, must be securely wiped or destroyed with a documented process and certificate of destruction where applicable.","domain":"SEC","severity":"medium","citations":[{"instrument":"DPDPA-2023","reference":"Section 8(5)"}],"evidence_required":[{"type":"document","description":"Media sanitisation policy + certificate of destruction register"}],"assessment_questions":[{"id":"Q1","prompt":"Is there a documented media sanitisation process and a register of end-of-life destructions?","type":"boolean","evidenceTypes":["document"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":8,"maxPenaltyINR":20000000},"remediation_patterns":["policy","config"],"tags":["always-applies","ops"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-SEC-007","library_version":"0.1.1","title":"Operate an incident response capability with rehearsed playbook","obligation":"Beyond breach notification, an operational incident response capability — on-call, escalation, runbook, post-mortem — is necessary to meet the 72-hour clock in practice, not just in policy.","domain":"SEC","severity":"high","citations":[{"instrument":"DPDPA-2023","reference":"Section 8(5), 8(6)"}],"evidence_required":[{"type":"document","description":"Incident response runbook + on-call roster"},{"type":"log","description":"Tabletop exercise record"}],"assessment_questions":[{"id":"Q1","prompt":"Do you have an on-call rotation and runbook for security incidents?","type":"boolean","evidenceTypes":["document","attestation"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":18,"maxPenaltyINR":50000000},"remediation_patterns":["breach-process","policy","training"],"tags":["always-applies"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-DAT-005","library_version":"0.1.1","title":"Verify the identity of a data principal before acting on rights requests","obligation":"Identity verification proportional to the sensitivity of the request is required before acting on access, correction, or erasure requests, to prevent unauthorised disclosure.","domain":"DAT","severity":"medium","citations":[{"instrument":"DPDPR-2025","reference":"Rule 14"}],"evidence_required":[{"type":"document","description":"Identity verification procedure"}],"assessment_questions":[{"id":"Q1","prompt":"Do you verify the identity of the data principal before fulfilling rights requests?","type":"boolean","evidenceTypes":["document","attestation"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":10,"maxPenaltyINR":20000000},"remediation_patterns":["policy","config"],"tags":["always-applies","rights"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null},{"id":"DPDPA-DAT-006","library_version":"0.1.1","title":"Provide data portability in a structured, commonly used format","obligation":"On request, the data principal is entitled to receive a copy of their personal data in a structured, commonly used and machine-readable format (Section 11(2)).","domain":"DAT","severity":"medium","citations":[{"instrument":"DPDPA-2023","reference":"Section 11(2)"}],"evidence_required":[{"type":"config","description":"Export pipeline producing JSON / CSV in a documented schema"}],"assessment_questions":[{"id":"Q1","prompt":"Can you export a user's data in a structured, machine-readable format on request?","type":"boolean","evidenceTypes":["config","log"],"dependsOn":[]}],"scoring":{"baseline":0,"weight":1,"penaltyPoints":10,"maxPenaltyINR":20000000},"remediation_patterns":["data-portability","config"],"tags":["always-applies","rights"],"sdf_only":false,"children_only":false,"introduced_in_version":"0.1.0","revised_in_version":null,"notes":null}]$seed$::jsonb);
