create function pg_temp.request(k integer default 51,prev uuid default null) returns jsonb language plpgsql as $$
declare ctx jsonb;begin
 ctx:=controller_security.public_control_review_context(pg_temp.id(31),pg_temp.id(1),pg_temp.id(41),((select record from saved_check)->>'id')::uuid,true);
 perform pg_temp.ok(not ctx?'error','trusted context '||ctx::text);
 return jsonb_build_object('version',2,'operationKey',pg_temp.id(k),'engagementId',pg_temp.id(41),'checkId',ctx->'checkId','expectedEstateId',pg_temp.id(71),'expectedPreviousReviewId',prev,
 'associationRef',(select jsonb_build_object('associationId',(a.value->>'snapshotText')::jsonb->>'id','associationSha256',a.value->>'snapshotSha256','targetId',(t.value->>'snapshotText')::jsonb->>'id','targetSha256',t.value->>'snapshotSha256','associationReceipt',jsonb_build_object('id',a.value->'receipt'->>'id','entryHash',a.value->'receipt'->>'entryHash')) from asset_operations a,asset_operations t where a.kind='association' and t.kind='target'),
 'expectedSource',jsonb_build_object('payloadSha256',ctx->'payloadSha256','catalogueManifestSha256',ctx->'catalogueManifestSha256','mappingVersion','public-evidence-1','libraryVersion','0.1.1','questionnaireDigest',ctx->'questionnaireDigest'),
 'answers','{}'::jsonb,'applicability',jsonb_build_object('sdfSelfAttested',null,'processesChildren',null,'processesHealth',null,'rationale','Human lacks internal evidence.'));
end$$;
create function pg_temp.save(v jsonb,a uuid default pg_temp.id(1),t uuid default pg_temp.id(31)) returns jsonb language plpgsql as $$
declare r jsonb;txt text;begin txt:=controller_security.canonical_questionnaire_json(v);set local role human_action_writer;
 r:=public.record_public_control_review_set(t,a,txt);reset role;return r;
exception when others then reset role;raise;end$$;
create function pg_temp.cancel(v jsonb,reason text default 'Operator explicitly abandons this unsaved review.',a uuid default pg_temp.id(1)) returns jsonb language plpgsql as $$
declare r jsonb;txt text;begin txt:=controller_security.canonical_questionnaire_json(v);set local role human_action_writer;
 r:=public.cancel_public_control_review_operation(pg_temp.id(31),a,txt,reason);reset role;return r;
exception when others then reset role;raise;end$$;
create function pg_temp.refused(v jsonb,why text,a uuid default pg_temp.id(1)) returns void language plpgsql as $$
declare n bigint;r jsonb;begin select count(*) into n from public.audit_ledger;r:=pg_temp.save(v,a);perform pg_temp.ok(r?'error','refused '||why||' '||r::text);perform pg_temp.ok((select count(*)=n from public.audit_ledger),'atomic refusal '||why);end$$;
