create function pg_temp.enqueue() returns jsonb language plpgsql as $$
declare v jsonb:=(select value from retained_review);s jsonb;r jsonb;
begin
 set local role human_action_writer;
 s:=public.resolve_public_control_assessment_source(pg_temp.id(31),pg_temp.id(1),pg_temp.id(201),pg_temp.id(41),(v->>'id')::uuid,v->>'request_sha256',v->>'snapshot_sha256');
 r:=public.enqueue_public_control_assessment_dispatch(pg_temp.id(201),pg_temp.id(31),pg_temp.id(1),pg_temp.id(81),pg_temp.id(71),pg_temp.id(41),pg_temp.id(201),s->>'inputSha256',repeat('b',64),clock_timestamp()+interval '10 minutes','arn:aws:kms:ap-south-1:123456789012:key/'||pg_temp.id(83)::text,decode(repeat('ab',12),'hex'),decode(repeat('ab',100),'hex'),decode(repeat('cd',32),'hex'),1,(select value->>'fingerprint' from policy),(v->>'id')::uuid,v->>'request_sha256',v->>'snapshot_sha256');
 reset role;return r;
exception when others then reset role;raise;end$$;
