create function pg_temp.computed_result() returns jsonb language sql stable as $$
 select jsonb_build_object('library_version','0.1.1','posture_score',0,'estimated_exposure_inr',0,
 'findings',(select jsonb_agg(jsonb_build_object('control_id',v->>'id','score',0,'risk_points',0,'rationale','Synthetic unknown questionnaire computation.')) from jsonb_array_elements(p.controls)v),
 'questionnaire_provenance',jsonb_build_object('version',1,'source_library_version','0.1.1','source_library_digest',p.library_digest,'estimates','provisional','review_required',true,
 'controls',(select jsonb_agg(jsonb_build_object('control_id',v->>'id','questions',x.questions,'known_boolean_question_count',jsonb_array_length(x.questions),'caller_affirmed_count',0,'caller_denied_count',0,'unknown_count',jsonb_array_length(x.questions),'answer_state',case when jsonb_array_length(x.questions)=0 then 'not_boolean_assessable' else 'unknown' end,'applicability_state',case when v->>'sdf_only'='true' or v->>'children_only'='true' then 'unknown' else 'unconditional' end)) from jsonb_array_elements(p.controls)v cross join lateral (select coalesce(jsonb_agg(jsonb_build_object('question_id',q->>'id','declaration','unknown') order by q->>'id'),'[]'::jsonb) questions from jsonb_array_elements(v->'assessment_questions')q where q->>'type'='boolean')x),
 'applicability',jsonb_build_object('sdf_self_attested',jsonb_build_object('value',null,'provenance','unknown'),'processes_children',jsonb_build_object('value',null,'provenance','unknown'),'processes_health',jsonb_build_object('value',null,'provenance','unknown'))))
 from public.workload_assessment_packets p where run_id=((select value from issued)->>'run_id')::uuid
$$;
select public.complete_workload_assessment(pg_temp.id(31),((select value from issued)->>'run_id')::uuid,pg_temp.id(81),repeat('b',64),(select library_digest from public.workload_assessment_packets where run_id=((select value from issued)->>'run_id')::uuid),pg_temp.computed_result(),clock_timestamp()+interval '5 minutes');
do $$begin
 begin perform controller_security.public_control_report_provenance(pg_temp.id(31),((select value from issued)->>'run_id')::uuid,pg_temp.id(41));raise exception 'ASSERTION: completed unfinalized source accepted';exception when check_violation then null;end;
end$$;
select pg_temp.ok(public.confirm_workload_assessment(pg_temp.id(31),((select value from issued)->>'run_id')::uuid)->>'status'='succeeded','real controller finalization');
create temporary table board_requested as select public.request_board_report(pg_temp.id(31),pg_temp.id(1),pg_temp.id(301),pg_temp.id(41),((select value from issued)->>'run_id')::uuid,'Asset-bound board draft',pg_temp.id(302)) value;
create temporary table auditor_requested as select public.request_statutory_report(pg_temp.id(31),pg_temp.id(1),pg_temp.id(303),pg_temp.id(41),((select value from issued)->>'run_id')::uuid,'auditor','Asset-bound auditor draft',pg_temp.id(304)) value;
select pg_temp.ok((select value->>'status'='requested' from board_requested),'board source3 requested');
select pg_temp.ok((select value->>'status'='requested' from auditor_requested),'auditor source3 requested');
create temporary table frozen as select source_text,source_sha256 from public.board_request_sources where request_id=((select value from board_requested)->>'requestId')::uuid;
select pg_temp.ok((select source_text::jsonb->>'schema_version'='3' and source_text::jsonb->'human_control_review'->>'kind'='public_control_review' and source_text::jsonb->'human_control_review'->'declarations_verified'='false'::jsonb and source_text::jsonb->'human_control_review'->'evidence_verified'='false'::jsonb from frozen),'versioned qualified source');
select pg_temp.ok((select source_text::jsonb->'human_control_review'->>'schema_version'='2' and source_text::jsonb->'human_control_review'->'review'->>'request_codec'='axiom-public-control-review-request-canonical-json-2' from frozen),'source3 requires review envelope2/codecs');
select pg_temp.ok((select source_text::jsonb->'human_control_review'->'review'->>'request_text'=(select value->>'request_text' from retained_review) and source_text::jsonb->'human_control_review'->'review'->>'snapshot_text'=(select value->>'snapshot_text' from retained_review) from frozen),'exact sparse judgments and normalized snapshot bytes retained');
select pg_temp.ok((select h->'worker_input'->>'text'=s.input_text and h->'worker_input'->>'sha256'=s.input_sha256 and h->'capture'->>'payload_text'=c.payload_text and h->'capture'->>'payload_sha256'=c.payload_sha256 and h->'capture'->>'page_sources_text'=c.page_sources::text and h->'capture'->>'page_sources_sha256'=encode(sha256(convert_to(c.page_sources::text,'UTF8')),'hex') and h->'catalogue'->>'manifest_sha256'=encode(sha256(convert_to(h->'catalogue'->>'manifest_text','UTF8')),'hex') from frozen cross join lateral (select source_text::jsonb->'human_control_review' h)x join public.public_control_assessment_sources s on s.job_id=pg_temp.id(201) join public.public_website_control_evidence c on c.check_id=(h->'capture'->>'check_id')::uuid),'exact payload, page provenance, mapping and worker bytes retained');
select pg_temp.ok((select source_text::jsonb->'human_control_review'=(select source_text::jsonb->'human_control_review' from frozen) from public.statutory_request_sources where request_id=((select value from auditor_requested)->>'requestId')::uuid),'board and auditor freeze identical qualified provenance');
select pg_temp.ok((select source_sha256=encode(sha256(convert_to(source_text,'UTF8')),'hex') from frozen),'outer source digest binds all evidence');

-- Both draft writers accept only the deterministic appendix for this source;
-- this SQL shape exercises custody gates (strict renderer validation is TS).
create function pg_temp.document(kind text) returns jsonb language plpgsql as $$
declare src jsonb;hash text;req jsonb;result jsonb;review jsonb;v jsonb;
begin
 if kind='board' then select source_text::jsonb,source_sha256 into src,hash from frozen;req:=(select value from board_requested);
 else select source_text::jsonb,source_sha256 into src,hash from public.statutory_request_sources where request_id=((select value from auditor_requested)->>'requestId')::uuid;req:=(select value from auditor_requested);end if;
 result:=(src->>'result_text')::jsonb;
 review:=controller_security.public_control_report_interpretation(result,case when kind='board' then 'Asset-bound board draft' else 'Asset-bound auditor draft' end);
 v:=jsonb_build_object('schema_version',4,'kind',case when kind='board' then 'board_report' else 'auditor_pack' end,'title',case when kind='board' then 'Asset-bound board draft' else 'Asset-bound auditor draft' end,'tenant_id',pg_temp.id(31),'engagement_id',pg_temp.id(41),'assessment_run_id',src->'assessment_run_id','source_sha256',hash,'assessment_result_digest',src->'result_sha256','library_digest',src->'controls_sha256','library_version','0.1.1','generated_at','2026-10-15T12:00:00.000Z','public_review_appendix',controller_security.public_control_report_appendix(src->'human_control_review'));
 v:=v||jsonb_build_object('asset_scope',controller_security.public_control_asset_report_appendix(src->'human_control_review'));
 if kind='board' then return v||jsonb_build_object('questionnaire_interpretation',review->'interpretation','executive_summary',review->'summary');end if;
 return v||jsonb_build_object('source_kind','finalized_assessment','request_id',req->'requestId','generated_by','statutory-report-builder','posture_score',result->'posture_score','finalized_at',src->'finalized_at','finalized_ledger_receipt',src#>'{receipts,finalized,id}','findings',result->'findings','controls',(select jsonb_agg(jsonb_build_object('id',c->'id','title',c->'title','domain',c->'domain','severity',c->'severity') order by ord) from jsonb_array_elements((src->>'controls_text')::jsonb) with ordinality x(c,ord)),'limitations','Assessment-derived findings only. No independent audit, evidence verification, or auditor attestation is represented.','questionnaire_review',review);
end$$;
select pg_temp.ok((select value->'questions'->0->>'judgment'='explicit' and value->'questions'->0->'answer'='null'::jsonb and value->'questions'->0->'candidates'->0->>'context'='ambiguous' and value->'questions'->0->'availableCandidateOrdinals'='[1]'::jsonb from jsonb_array_elements(pg_temp.document('board')->'public_review_appendix'->'controls') where value->>'controlId'='DPDPA-GOV-001'),'explicit null/rationale and qualified source candidate retained');
select pg_temp.ok((select value->'questions'->0->>'judgment'='omitted' and value->'questions'->0->'rationale'='null'::jsonb from jsonb_array_elements(pg_temp.document('board')->'public_review_appendix'->'controls') where value->>'controlId'='DPDPA-GOV-002'),'omitted judgment has no invented rationale');
create function pg_temp.draft(kind text,body jsonb) returns jsonb language sql as $$
 select case when kind='board' then public.record_board_report_draft(pg_temp.id(31),pg_temp.id(1),((select value from board_requested)->>'requestId')::uuid,body::text,'<p>Unpublished synthetic draft</p>',pg_temp.id(401))
 else public.record_source_bound_statutory_draft(pg_temp.id(31),pg_temp.id(1),((select value from auditor_requested)->>'requestId')::uuid,body::text,'<p>Unpublished synthetic draft</p>',pg_temp.id(402)) end
$$;
do $$declare kind text;doc jsonb;r jsonb;report public.reports;begin
 foreach kind in array array['board','auditor'] loop
  doc:=pg_temp.document(kind);
  perform pg_temp.ok(pg_temp.draft(kind,jsonb_set(doc,'{schema_version}','3'))->>'error'='assessment_source_conflict','source3 refuses downgraded document');
  perform pg_temp.ok(pg_temp.draft(kind,jsonb_set(doc,'{source_sha256}',to_jsonb(repeat('f',64))))->>'error'='assessment_source_conflict','cannot swap frozen source');
  perform pg_temp.ok(pg_temp.draft(kind,doc-'public_review_appendix')->>'error'='assessment_source_conflict','source3 refuses missing appendix');
  perform pg_temp.ok(pg_temp.draft(kind,jsonb_set(doc,'{public_review_appendix,declarationsVerified}','true'))->>'error'='assessment_source_conflict','cannot invent verified declarations');
  perform pg_temp.ok(pg_temp.draft(kind,jsonb_set(doc,'{public_review_appendix,reviewId}',to_jsonb(pg_temp.id(999)::text)))->>'error'='assessment_source_conflict','cannot swap review appendix');
  perform pg_temp.ok(pg_temp.draft(kind,doc-'asset_scope')->>'error'='assessment_source_conflict','source3 requires asset appendix');
  perform pg_temp.ok(pg_temp.draft(kind,jsonb_set(doc,'{asset_scope,ownership_verified}','true'))->>'error'='assessment_source_conflict','cannot certify ownership');
  perform pg_temp.ok(pg_temp.draft(kind,jsonb_set(doc,'{asset_scope,system,id}',to_jsonb(pg_temp.id(999)::text)))->>'error'='assessment_source_conflict','cannot graft another system');
  perform pg_temp.ok(pg_temp.draft(kind,jsonb_set(doc,'{asset_scope,target,url}','"https://other.org/"'))->>'error'='assessment_source_conflict','cannot graft another URL');
  r:=pg_temp.draft(kind,doc);perform pg_temp.ok(r?'reportId','source3 draft recorded '||kind||' '||r::text);
  perform pg_temp.ok(pg_temp.draft(kind,doc)->>'replayed'='true','exact document replay');
  select * into report from public.reports where id=(r->>'reportId')::uuid;
  perform pg_temp.ok(report.content=doc and report.content_sha256=encode(sha256(convert_to(doc::text,'UTF8')),'hex'),'exact document persisted');
  perform pg_temp.ok(public.release_report(pg_temp.id(31),report.id,pg_temp.id(1),report.content_sha256,repeat('a',64),gen_random_uuid())->>'error'='not_approved','draft cannot release');
  perform pg_temp.ok(public.review_report(pg_temp.id(31),report.id,'approved',null,pg_temp.id(1),report.content_sha256,gen_random_uuid())->>'status'='approved','human review remains required and records exact content');
  perform pg_temp.ok(public.release_report(pg_temp.id(31),report.id,pg_temp.id(1),report.content_sha256,repeat('a',64),gen_random_uuid())->>'error'='report_artifact_unverified','human review cannot bypass sealed artifact custody');
 end loop;
end$$;

